def process_csv_file(file_path):
    daily_averages = {}
    per_file_stats = {}
    skipped_lines = []

    with open(file_path, newline='', encoding='utf-8') as f:
        next(f)  # Skip header
        for line_number, line in enumerate(f, start=2):  # Start line numbers at 2
            line = line.strip()
            if not line:
                continue

            parts = line.split(',', 2)
            if len(parts) < 3:
                skipped_lines.append({
                    'file_path': file_path,
                    'line_number': line_number,
                    'original_line': line,
                    'reason': 'not enough fields'
                })
                continue

            timestamp, site, value = parts

            if value.strip().lower() in ['n/a', 'na', 'none', '']:
                skipped_lines.append({
                    'file_path': file_path,
                    'line_number': line_number,
                    'original_line': line,
                    'reason': 'invalid value'
                })
                # Track per-site skipped count
                if site not in per_file_stats:
                    per_file_stats[site] = {'rows_used': 0, 'rows_skipped': 0}
                per_file_stats[site]['rows_skipped'] += 1
                continue

            if ',' in value:
                repaired_value = value.replace(',', '.')
                try:
                    numeric_value = float(repaired_value)
                    if 0 <= numeric_value <= 20:
                        value = repaired_value
                        # Track per-site used count
                        if site not in per_file_stats:
                            per_file_stats[site] = {'rows_used': 0, 'rows_skipped': 0}
                        per_file_stats[site]['rows_used'] += 1
                    else:
                        skipped_lines.append({
                            'file_path': file_path,
