                    skipped_lines.append({
                        'file_path': file_path,
                        'line_number': line_number,
                        'original_line': line,
                        'reason': 'invalid numeric value'
                    })
                    per_file_stats[site]['rows_skipped'] += 1
                    continue

            # Group by site and date
            date_part = timestamp.split()[0]

            if site not in daily_averages:
                daily_averages[site] = {}

            if date_part not in daily_averages[site]:
                daily_averages[site][date_part] = {'total': 0.0, 'count': 0}

            daily_averages[site][date_part]['total'] += float(value)
            daily_averages[site][date_part]['count'] += 1

    return daily_averages, per_file_stats, skipped_lines
